-- Arcanis: zindan gunlugu verisi. Kendi cumlelerimizle yazilmis ozet notlar; seviye araliklari yaklasiktir
-- (WoW Forever surumune gore duzeltilebilir). faction yoksa iki taraf da girer.
local _, ns = ...

-- entrance: zindan girisi { zone, x, y, path = { { x, y, tur }, ... } } (path: disaridan girise yaklasma noktalari,
--   tur: path/jump/swim/elevator/stairs/bridge/cave/building/ramp/chain/balcony); ok, rehber ve dunya haritasi
--   isareti bunu kullanir. alt: ikinci giris(ler) ayni bicimde + name. how: nasil gidilir (kendi cumlelerimiz).
-- Ek veri (gorevler, loot) Data/Dungeons/<id>.lua icinden eklenir: ns.DungeonExtra("dm", { quests = {...}, loot = {...} }).
-- quests: { id, name, level?, side?, giver?, note? }   loot: { boss, items = { { id, n }, ... } }
-- Esya adi/kalitesi oyunda esya kimligiyle cozulur; n yalnizca onbellekte yokken yedek addir.
-- raid = true: raid; seviye onerisine (soru, Mentor) ve zindan yukseltmelerine girmez. verify = true: giris noktasi ve
-- veri oyunda dogrulanmali (Forever'in yeni zindanlari; oyuncu portala girince gercek giris Journal.db.seenEntrance'a yazilir).
ns.DungeonExtras = {}
function ns.DungeonExtra(id, extra) ns.DungeonExtras[id] = extra end

