    notes = { enUS = "An ancient titan vault in the Badlands, full of stone guardians and Dark Iron dwarves. Archaedas wakes in the last chamber and calls the stone keepers around him, so be ready for extra adds.", trTR = "Badlands'te, taş bekçiler ve Dark Iron cüceleriyle dolu eski bir titan mahzeni. Archaedas son odada uyanır ve çevresindeki taş bekçileri çağırır; ek düşmanlara hazır ol." },
