  },
  { id = "brd", name = "Blackrock Depths", zone = "Searing Gorge", minLevel = 52, maxLevel = 60, art = "brd", entrance = { zone = "Searing Gorge", x = 27.07, y = 72.51, path = { { 26.88, 83.87, "path" } } },
